import test from'node:test';import assert from'node:assert/strict';import{create,evaluate,swap,compare}from'./engine.js';
test('redistributing fixed errors preserves accuracy but changes decision loss',()=>{const a=create(),b=swap(a,0,3),x=evaluate(a),y=evaluate(b);assert.equal(x.mae,y.mae);assert.equal(x.rmse,y.rmse);assert.notEqual(x.loss,y.loss);assert.deepEqual(swap(b,3,0),a);assert.equal(a.order[0],0);});
test('threshold equality means act and losses count only errors',()=>{const s=create();s.actual[0]=40;const r=evaluate(s);assert.equal(r.rows[0].forecast,60);assert.equal(r.rows[0].kind,'falseAlarm');assert.equal(r.rows[0].cost,3);assert.equal(r.loss,r.misses*8+r.falseAlarms*3);s.miss=0;s.falseAlarm=0;assert.equal(evaluate(s).loss,0);});
test('pinned allocation shares current actuals threshold and loss assumptions',()=>{const a=create(),b=swap(a,0,3);b.threshold=75;b.miss=15;b.actual[0]=80;assert.deepEqual(compare(b,a),evaluate({...b,order:a.order}));assert.equal(a.actual[0],40);});
